window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ce5a0ec0f8fa2874"]={"versions": [{"id": "FIG-ce5a0ec0f8fa2874", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenmodell zur Darstellung des AUTOSAR CAN-Kommunikationsstacks (Classic Platform) mit Fokus auf die Kanalabbildung („Physical channel view definition example B“). Das Diagramm veranschaulicht das Mapping zwischen der logischen Netzwerksicht („Network view“) oberhalb des CAN State Managers und der physikalischen Kanalsicht („Physical channel view“) unterhalb des CAN State Managers bis hinunter zur Hardware-Ebene (Controller und Transceiver).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in folgende Module und Hardware-Entitäten:</p>\n<ul class=\"fig-list\">\n<li>Obere Ebene („Network view“): <code>COM Manager</code> flankiert von <code>CAN NM A</code> und <code>CAN NM B</code>.</li>\n<li>Management- und Abstraktionsebene: <code>CAN State Manager</code> (verbindet Network view mit Physical channel view) und <code>CAN Interface</code> (CanIf).</li>\n<li>Treiberebene (Software):</li>\n<li>Linker Zweig: <code>CAN transc. driver 0</code> und <code>CAN driver 0</code>.</li>\n<li>Rechter Zweig: <code>CAN driver 1</code>, <code>CAN driver 2</code> und <code>CAN transc. driver 1</code>.</li>\n<li>Steuer- und Datenflüsse zwischen CanIf und Treibern sind über gerichtete Pfeile (bidirektional zu den Transceiver-Treibern, getrennte Sende-/Empfangspfeile zu den CAN-Treibern) angebunden.</li>\n<li>Hardware- und Kanalebene:</li>\n<li>Linker Zweig: <code>CAN controller 0</code> und <code>CAN controller 1</code> (beide vom selben Typ, angesteuert über den gemeinsamen <code>CAN driver 0</code>), die über eine logische Und-Verknüpfung (<code>&amp;</code>) auf der Tx-Leitung sowie eine gemeinsame Verzweigung auf der Rx-Leitung auf einen gemeinsamen <code>CAN transceiver 0</code> gekoppelt sind.</li>\n<li>Rechter Zweig: <code>CAN controller 2</code> (angesteuert durch <code>CAN driver 1</code>) und <code>CAN controller 3</code> (angesteuert durch <code>CAN driver 2</code>), ebenfalls über Tx-Und-Gatter (<code>&amp;</code>) und Rx-Verbindung an <code>CAN transceiver 1</code> gekoppelt.</li>\n<li>Physische Busse: Transceiver 0 führt auf <code>CAN network A e.g CAN class C</code>, Transceiver 1 auf <code>CAN network B e.g. CAN class B</code>.</li>\n<li>Zusätzliche Annotation: „Use Case: 1:n relation between CAN network and physical channel“ sowie Hinweis „Same types of CAN controllers“ für Controller 0 und 1.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Verschaltungsdiagramm ohne explizite Ablaufsequenz. Dargestellt ist der funktionale Signal- und Steuerfluss:</p>\n<ul class=\"fig-list\">\n<li>Sende- und Empfangsrichtung (Tx/Rx) zwischen Controllern und Transceivern: Mehrere Controller teilen sich denselben physikalischen Transceiver (Tx-Signale werden über ein logisches Und-Gatter zusammengeführt, Rx-Signale parallel an beide Controller verteilt).</li>\n<li>Die Treiberschicht abstrahiert die Controller-Hardware gegenüber dem CAN Interface; das CAN Interface bildet die Schnittstelle zur physikalischen Kanalsicht für den CAN State Manager ab, welcher die Netze koordiniert an den COM Manager meldet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturbeispiel für Mehrfach-Controller-Konfigurationen an einem gemeinsamen Transceiver bzw. physikalischen Kanal (1:n-Beziehung zwischen CAN-Netzwerk und physischem Kanal). Für Integratoren und Treiberentwickler relevant hinsichtlich:</p>\n<ul class=\"fig-list\">\n<li>Unterstützung identischer Controllertypen über eine Treiberinstanz (<code>CAN driver 0</code>) vs. getrennter Treiberinstanzen (<code>CAN driver 1</code> und <code>CAN driver 2</code>) für unterschiedliche Controller.</li>\n<li>Hardwarenahe Zusammenschaltung von Tx/Rx-Leitungen bei Multi-Controller-Nutzung an einem Transceiver.</li>\n<li>Trennung zwischen Network View (Netzwerkmanagement, COM Manager) und Physical Channel View (Zustandsverwaltung im CAN State Manager und CanIf).</li>\n</ul>"}, {"id": "FIG-b1caecc026c6b109", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenmodell zur Darstellung des AUTOSAR CAN-Kommunikationsstacks (Classic Platform) mit Fokus auf die Kanalabbildung („Physical channel view definition example B“). Das Diagramm veranschaulicht das Mapping zwischen der logischen Netzwerksicht („Network view“) oberhalb des CAN State Managers und der physikalischen Kanalsicht („Physical channel view“) unterhalb des CAN State Managers bis hinunter zur Hardware-Ebene (Controller und Transceiver).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in folgende Module und Hardware-Entitäten:</p>\n<ul class=\"fig-list\">\n<li>Obere Ebene („Network view“): <code>COM Manager</code> flankiert von <code>CAN NM A</code> und <code>CAN NM B</code>.</li>\n<li>Management- und Abstraktionsebene: <code>CAN State Manager</code> (verbindet Network view mit Physical channel view) und <code>CAN Interface</code> (CanIf).</li>\n<li>Treiberebene (Software):</li>\n<li>Linker Zweig: <code>CAN transc. driver 0</code> und <code>CAN driver 0</code>.</li>\n<li>Rechter Zweig: <code>CAN driver 1</code>, <code>CAN driver 2</code> und <code>CAN transc. driver 1</code>.</li>\n<li>Steuer- und Datenflüsse zwischen CanIf und Treibern sind über gerichtete Pfeile (bidirektional zu den Transceiver-Treibern, getrennte Sende-/Empfangspfeile zu den CAN-Treibern) angebunden.</li>\n<li>Hardware- und Kanalebene:</li>\n<li>Linker Zweig: <code>CAN controller 0</code> und <code>CAN controller 1</code> (beide vom selben Typ, angesteuert über den gemeinsamen <code>CAN driver 0</code>), die über eine logische Und-Verknüpfung (<code>&amp;</code>) auf der Tx-Leitung sowie eine gemeinsame Verzweigung auf der Rx-Leitung auf einen gemeinsamen <code>CAN transceiver 0</code> gekoppelt sind.</li>\n<li>Rechter Zweig: <code>CAN controller 2</code> (angesteuert durch <code>CAN driver 1</code>) und <code>CAN controller 3</code> (angesteuert durch <code>CAN driver 2</code>), ebenfalls über Tx-Und-Gatter (<code>&amp;</code>) und Rx-Verbindung an <code>CAN transceiver 1</code> gekoppelt.</li>\n<li>Physische Busse: Transceiver 0 führt auf <code>CAN network A e.g CAN class C</code>, Transceiver 1 auf <code>CAN network B e.g. CAN class B</code>.</li>\n<li>Zusätzliche Annotation: „Use Case: 1:n relation between CAN network and physical channel“ sowie Hinweis „Same types of CAN controllers“ für Controller 0 und 1.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Verschaltungsdiagramm ohne explizite Ablaufsequenz. Dargestellt ist der funktionale Signal- und Steuerfluss:</p>\n<ul class=\"fig-list\">\n<li>Sende- und Empfangsrichtung (Tx/Rx) zwischen Controllern und Transceivern: Mehrere Controller teilen sich denselben physikalischen Transceiver (Tx-Signale werden über ein logisches Und-Gatter zusammengeführt, Rx-Signale parallel an beide Controller verteilt).</li>\n<li>Die Treiberschicht abstrahiert die Controller-Hardware gegenüber dem CAN Interface; das CAN Interface bildet die Schnittstelle zur physikalischen Kanalsicht für den CAN State Manager ab, welcher die Netze koordiniert an den COM Manager meldet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturbeispiel für Mehrfach-Controller-Konfigurationen an einem gemeinsamen Transceiver bzw. physikalischen Kanal (1:n-Beziehung zwischen CAN-Netzwerk und physischem Kanal). Für Integratoren und Treiberentwickler relevant hinsichtlich:</p>\n<ul class=\"fig-list\">\n<li>Unterstützung identischer Controllertypen über eine Treiberinstanz (<code>CAN driver 0</code>) vs. getrennter Treiberinstanzen (<code>CAN driver 1</code> und <code>CAN driver 2</code>) für unterschiedliche Controller.</li>\n<li>Hardwarenahe Zusammenschaltung von Tx/Rx-Leitungen bei Multi-Controller-Nutzung an einem Transceiver.</li>\n<li>Trennung zwischen Network View (Netzwerkmanagement, COM Manager) und Physical Channel View (Zustandsverwaltung im CAN State Manager und CanIf).</li>\n</ul>"}, {"id": "FIG-c506f69b9f97525f", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenmodell zur Darstellung des AUTOSAR CAN-Kommunikationsstacks (Classic Platform) mit Fokus auf die Kanalabbildung („Physical channel view definition example B“). Das Diagramm veranschaulicht das Mapping zwischen der logischen Netzwerksicht („Network view“) oberhalb des CAN State Managers und der physikalischen Kanalsicht („Physical channel view“) unterhalb des CAN State Managers bis hinunter zur Hardware-Ebene (Controller und Transceiver).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in folgende Module und Hardware-Entitäten:</p>\n<ul class=\"fig-list\">\n<li>Obere Ebene („Network view“): <code>COM Manager</code> flankiert von <code>CAN NM A</code> und <code>CAN NM B</code>.</li>\n<li>Management- und Abstraktionsebene: <code>CAN State Manager</code> (verbindet Network view mit Physical channel view) und <code>CAN Interface</code> (CanIf).</li>\n<li>Treiberebene (Software):</li>\n<li>Linker Zweig: <code>CAN transc. driver 0</code> und <code>CAN driver 0</code>.</li>\n<li>Rechter Zweig: <code>CAN driver 1</code>, <code>CAN driver 2</code> und <code>CAN transc. driver 1</code>.</li>\n<li>Steuer- und Datenflüsse zwischen CanIf und Treibern sind über gerichtete Pfeile (bidirektional zu den Transceiver-Treibern, getrennte Sende-/Empfangspfeile zu den CAN-Treibern) angebunden.</li>\n<li>Hardware- und Kanalebene:</li>\n<li>Linker Zweig: <code>CAN controller 0</code> und <code>CAN controller 1</code> (beide vom selben Typ, angesteuert über den gemeinsamen <code>CAN driver 0</code>), die über eine logische Und-Verknüpfung (<code>&amp;</code>) auf der Tx-Leitung sowie eine gemeinsame Verzweigung auf der Rx-Leitung auf einen gemeinsamen <code>CAN transceiver 0</code> gekoppelt sind.</li>\n<li>Rechter Zweig: <code>CAN controller 2</code> (angesteuert durch <code>CAN driver 1</code>) und <code>CAN controller 3</code> (angesteuert durch <code>CAN driver 2</code>), ebenfalls über Tx-Und-Gatter (<code>&amp;</code>) und Rx-Verbindung an <code>CAN transceiver 1</code> gekoppelt.</li>\n<li>Physische Busse: Transceiver 0 führt auf <code>CAN network A e.g CAN class C</code>, Transceiver 1 auf <code>CAN network B e.g. CAN class B</code>.</li>\n<li>Zusätzliche Annotation: „Use Case: 1:n relation between CAN network and physical channel“ sowie Hinweis „Same types of CAN controllers“ für Controller 0 und 1.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Verschaltungsdiagramm ohne explizite Ablaufsequenz. Dargestellt ist der funktionale Signal- und Steuerfluss:</p>\n<ul class=\"fig-list\">\n<li>Sende- und Empfangsrichtung (Tx/Rx) zwischen Controllern und Transceivern: Mehrere Controller teilen sich denselben physikalischen Transceiver (Tx-Signale werden über ein logisches Und-Gatter zusammengeführt, Rx-Signale parallel an beide Controller verteilt).</li>\n<li>Die Treiberschicht abstrahiert die Controller-Hardware gegenüber dem CAN Interface; das CAN Interface bildet die Schnittstelle zur physikalischen Kanalsicht für den CAN State Manager ab, welcher die Netze koordiniert an den COM Manager meldet.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architekturbeispiel für Mehrfach-Controller-Konfigurationen an einem gemeinsamen Transceiver bzw. physikalischen Kanal (1:n-Beziehung zwischen CAN-Netzwerk und physischem Kanal). Für Integratoren und Treiberentwickler relevant hinsichtlich:</p>\n<ul class=\"fig-list\">\n<li>Unterstützung identischer Controllertypen über eine Treiberinstanz (<code>CAN driver 0</code>) vs. getrennter Treiberinstanzen (<code>CAN driver 1</code> und <code>CAN driver 2</code>) für unterschiedliche Controller.</li>\n<li>Hardwarenahe Zusammenschaltung von Tx/Rx-Leitungen bei Multi-Controller-Nutzung an einem Transceiver.</li>\n<li>Trennung zwischen Network View (Netzwerkmanagement, COM Manager) und Physical Channel View (Zustandsverwaltung im CAN State Manager und CanIf).</li>\n</ul>"}], "trans": [{"from": "FIG-ce5a0ec0f8fa2874", "to": "FIG-b1caecc026c6b109", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-b1caecc026c6b109", "to": "FIG-c506f69b9f97525f", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Beschriftungsbox unten („Use Case: 1:n relation between CAN network and physical channel“): Text am unteren Bildrand abgeschnitten / vertikal verkürzt.</li>\n</ul>"}]};
